fn ring(p: vec2f, c: vec2f, age: f32, k: f32) -> f32 {
  if (age <= 0.0) { return 0.0; }
  let d = distance(p, c);
  let r = age * 0.62;
  let env = exp(-abs(d - r) * 7.0) * exp(-age * 0.75) * smoothstep(0.0, 0.08, age);
  return sin((d - r) * 52.0) * env * k;
}
fn h(uv: vec2f, t: f32) -> f32 {
  let asp = vec2f(rexx.size.x / rexx.size.y, 1.0);
  let p = uv * asp;
  var s = 0.0;
  s += ring(p, params.drop1 * asp, t - 0.4, 1.0);
  s += ring(p, params.drop2 * asp, t - 1.6, 0.9);
  s += 0.06 * sin(p.x * 24.0 + t * 1.8) * sin(p.y * 20.0 - t * 1.3);
  return s;
}
fn effect(uv: vec2f, t: f32) -> vec4f {
  let e = vec2f(1.5, 0.0) / rexx.size;
  let hx = h(uv + e.xy, t) - h(uv - e.xy, t);
  let hy = h(uv + e.yx, t) - h(uv - e.yx, t);
  let g = vec2f(hx, hy) * params.strength;
  let c = textureSampleLevel(input, samp, uv + g, 0.0);
  let n = normalize(vec3f(-g * 55.0, 1.0));
  let l = normalize(vec3f(-0.35, -0.55, 0.75));
  let hv = normalize(l + vec3f(0.0, 0.0, 1.0));
  let spec = pow(max(dot(n, hv), 0.0), 90.0) * params.shine;
  return vec4f(c.rgb + vec3f(spec), 1.0);
}
